function insertionSort(values) {
  for (let i = 1; i < values.length; i += 1) {
    const card = values[i]
    let j = i - 1
    while (j >= 0 && values[j] > card) {
      values[j + 1] = values[j]
      j -= 1
    }
    values[j + 1] = card
  }
  return values
}

